package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.sequence.*;
import static org.jlinalg.cli.FollowupSupport.hash;

/** Native chromVAR deviations from explicit prepared peak backgrounds, with portable captured verification. */
public final class ChromVarRequestCli {
    private ChromVarRequestCli() { }
    private static final List<String> INPUTS=List.of("counts","peak_features","cells","motif_labels","annotation_peaks","motif_matrix","background","groups","group_levels","expectation");
    private static final Set<String> ALLOWED=Set.of("schema_version","mode","profile","out","genome_build","motif_collection","background_provenance","counts","peak_features","cells","motif_labels","annotation_peaks","motif_matrix","background","groups","group_levels","expectation","norm","maximum_work","maximum_entries","maximum_background_values","maximum_sample_memberships","maximum_output_values","maximum_input_bytes","maximum_output_bytes");
    private static final String ACTION="Read WARNINGS.md, deviations.tsv, expectations.tsv, motif-summary.tsv, diagnostics.json and captured inputs/request. Preserve every attempt and choose NEW output paths after correcting named input/identity/source/capacity errors. Review prepared background provenance, source NA/NaN/Inf, expected-count filtering and zero background variance. Native DEVIATIONS/VERIFY require Java and do not install software. GC/intensity sampling and motif scanning require separate validated upstream preparation; unavailable/forbidden dependencies mean SKIP3 for those dependent analyses. Supply/install exact requirements only where permitted, otherwise skip them. Hashes prove integrity, not authenticity or biological validity.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream out,PrintStream err){
        try {
            if(args.length==1&&args[0].equals("--help")){emit(out,"ChromVarRequestCli --request UTF8_JSON\nModes: DEVIATIONS (explicit prepared backgrounds) or VERIFY (no R). Relative paths resolve against the request directory.\n"+ACTION);return 0;}
            if(args.length!=2||!args[0].equals("--request"))throw new IOException("Require --request UTF8_JSON");Path path=Path.of(args[1]).toAbsolutePath().normalize();var request=read(path);schema(request);
            if("VERIFY".equals(request.get("mode"))){keys(request,Set.of("schema_version","mode","analysis"));verify(resolve(path.getParent(),text(request,"analysis"),false));emit(out,"Verified native chromVAR capture without R");return 0;}
            validate(request);Path destination=resolve(path.getParent(),text(request,"out"),false);int[] code={0};
            FollowupSupport.externalTransaction(Map.of("out",destination.toString()),"native-chromvar-deviations-development",(stage,manifest)->{
                List<String> warnings=new ArrayList<>();try {
                    String before=hash(path);Files.copy(path,stage.resolve("source-request.json"));if(!before.equals(hash(path))||!before.equals(hash(stage.resolve("source-request.json"))))throw new IOException("Request changed during capture");var captured=capture(request,path.getParent(),stage,manifest);json(stage.resolve("request.json"),captured);copySources(stage);Prepared prepared=prepare(captured,stage);checkInputs(stage,manifest,captured);warnings.addAll(prepared.warnings);tables(stage,prepared,false,integer(captured,"maximum_output_bytes",2_000_000_000L,1,20_000_000_000L));json(stage.resolve("diagnostics.json"),diagnostics(prepared));json(stage.resolve("verify-request.json"),Map.of("schema_version",1,"mode","VERIFY","analysis","."));manifest.put("analysis_status","completed-with-warnings");manifest.put("mode","DEVIATIONS");manifest.put("profile",captured.get("profile"));manifest.put("source_request_sha256",before);manifest.put("engine","native-java");manifest.put("upstream_background_sampling_performed",false);manifest.put("motif_scanning_performed",false);manifest.put("historical_whole_packages_executed",false);manifest.put("full_Signac_workflow_available",false);
                } catch(Exception failure) {
                    code[0]=2;manifest.put("analysis_status","failed");manifest.put("error",failure.toString());warnings.add("FAIL2 — NO CHROMVAR RESULT ADMITTED: "+failure);for(String name:List.of("deviations.tsv","expectations.tsv","motif-summary.tsv","diagnostics.json","verify-request.json"))if(Files.exists(stage.resolve(name)))Files.move(stage.resolve(name),stage.resolve("retained-partial-"+name));
                }
                Files.writeString(stage.resolve("WARNINGS.md"),warningText(warnings,code[0]),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);json(stage.resolve("analysis-status.json"),Map.of("status",manifest.get("analysis_status")));json(stage.resolve("manifest.json"),manifest);
            });seal(destination);if(code[0]==0){verify(destination);emit(out,"Completed native chromVAR deviations: "+destination);}else emit(err,"FAIL2 — NO CHROMVAR RESULT ADMITTED: "+destination);emit(err,"WARNINGS / REQUIRED ACTION: "+destination.resolve("WARNINGS.md")+"\n"+ACTION);return code[0];
        } catch(OutOfMemoryError failure){emit(err,"FAIL2 — NO CHROMVAR RESULT ADMITTED: Java memory capacity exhausted. Preserve partials; use a suitable heap and explicit capacities with NEW outputs. "+ACTION);return 2;}
        catch(Exception failure){emit(err,"FAIL2 — Native chromVAR request/verification failed: "+failure+"\n"+ACTION);return 2;}
    }
    private static void validate(Map<String,Object> r)throws IOException {
        schema(r);keys(r,ALLOWED);if(!"DEVIATIONS".equals(r.get("mode")))throw new IOException("Require DEVIATIONS or VERIFY");profile(r);
        for(String key:List.of("out","genome_build","motif_collection","background_provenance","counts","peak_features","cells","motif_labels","background"))text(r,key);
        if((r.get("annotation_peaks")!=null)==(r.get("motif_matrix")!=null))throw new IOException("Choose exactly one explicit annotation_peaks index-list or binary motif_matrix");if((r.get("groups")==null)!=(r.get("group_levels")==null))throw new IOException("groups and group_levels must be supplied together");for(String key:INPUTS)if(r.get(key)!=null)text(r,key);
        if(r.containsKey("norm")&&!(r.get("norm") instanceof Boolean))throw new IOException("norm must be a JSON boolean");numericLimits(r);ioLimits(r);integer(r,"maximum_output_bytes",2_000_000_000L,1,20_000_000_000L);
    }
    private record Prepared(ChromVarDeviations.Counts counts,ChromVarIO.Annotations annotations,int iterations,double[] expectation,ChromVarDeviations.Result result,int missingGroups,boolean suppliedExpectation,List<String> warnings) { }
    private static Prepared prepare(Map<String,Object> r,Path root)throws IOException {
        validate(r);var numeric=numericLimits(r);var io=ioLimits(r);var cancelled=(java.util.function.BooleanSupplier)()->Thread.currentThread().isInterrupted();var counts=ChromVarIO.counts(input(r,"counts",root),input(r,"peak_features",root),input(r,"cells",root),io,numeric,cancelled);boolean matrix=r.get("motif_matrix")!=null;var annotations=ChromVarIO.annotations(input(r,matrix?"motif_matrix":"annotation_peaks",root),input(r,"peak_features",root),input(r,"motif_labels",root),counts.peaks(),matrix,io,numeric,cancelled);int[][] background=ChromVarIO.background(input(r,"background",root),counts.peaks(),io,numeric,cancelled);ChromVarIO.Groups groups=r.get("groups")==null?null:ChromVarIO.groups(input(r,"groups",root),input(r,"group_levels",root),counts.cells(),io,cancelled);List<String> warnings=new ArrayList<>();double[] expectation;
        if(r.get("expectation")==null){var e=ChromVarDeviations.expectations(counts,Boolean.TRUE.equals(r.get("norm")),groups==null?null:groups.grouping(),profile(r),numeric,cancelled);expectation=e.values();warnings.addAll(e.warnings());}
        else{expectation=ChromVarIO.expectation(input(r,"expectation",root),counts.peaks(),io,cancelled);warnings.add("EXPLICIT_EXPECTATION: declared expectation values enter the original core unchanged; no sum-to-one normalization, imputation or finite-value repair is applied. norm/groups do not override an explicit expectation file.");}
        var result=ChromVarDeviations.compute(counts,annotations.ids(),annotations.peaks(),background,expectation,profile(r),numeric,cancelled);warnings.addAll(result.warnings());if(groups!=null&&groups.missingAssignments()>0)warnings.add("SOURCE_FACTOR_LEVELS: "+groups.missingAssignments()+" blank/unmatched group labels map to missing factor assignments under the declared levels. Review the raw group and level files.");if(annotations.repeatedMembers()>0)warnings.add("ANNOTATION_STORAGE: "+annotations.repeatedMembers()+" repeated input members/coordinates were handled under the explicit "+annotations.format()+" contract. Index-list multiplicity is retained; pattern-matrix duplicate coordinates use logical union.");warnings.add("SOURCE_SINGLE_PEAK_PRECISION: original single-peak sparse-matrix column means use sequential double accumulation. With zero background SD, rounding residuals can produce Inf/-Inf instead of NaN. These source outputs remain explicit and are not validated discoveries.");warnings.add("DECLARED_PROVENANCE: genome_build, motif_collection and background_provenance are declarations. Verify assembly, peak/motif identities and preparation settings; native scoring does not certify upstream sampling or scanning.");return new Prepared(counts,annotations,background.length==0?0:background[0].length,expectation,result,groups==null?0:groups.missingAssignments(),r.get("expectation")!=null,List.copyOf(warnings));
    }
    private static ChromVarDeviations.Limits numericLimits(Map<String,Object> r)throws IOException {var d=ChromVarDeviations.Limits.defaults();return new ChromVarDeviations.Limits(d.peaks(),d.cells(),(int)integer(r,"maximum_entries",2_000_000,0,20_000_000),d.annotations(),d.annotationIndices(),integer(r,"maximum_background_values",d.backgroundValues(),0,100_000_000),integer(r,"maximum_sample_memberships",d.sampleMemberships(),0,100_000_000),integer(r,"maximum_output_values",d.outputValues(),1,200_000_000),d.intermediateValues(),integer(r,"maximum_work",d.maximumWork(),1,10_000_000_000_000L));}
    private static ChromVarIO.Limits ioLimits(Map<String,Object> r)throws IOException {return new ChromVarIO.Limits(integer(r,"maximum_input_bytes",2_000_000_000L,1,20_000_000_000L),1_000_000,(int)integer(r,"maximum_entries",2_000_000,0,20_000_000));}
    private static Map<String,Object> capture(Map<String,Object> r,Path parent,Path stage,Map<String,Object> manifest)throws IOException {var captured=new LinkedHashMap<>(r);captured.put("out",".");Map<String,Object> hashes=new LinkedHashMap<>();Path directory=Files.createDirectory(stage.resolve("input"));int index=0;long limit=ioLimits(r).bytes();for(String key:INPUTS)if(r.get(key)!=null){Path source=resolve(parent,text(r,key),false);if(!Files.isRegularFile(source)||Files.size(source)>limit)throw new IOException("Input unavailable/excessive: "+key);String name="input/file-"+index++;Path copy=stage.resolve(name);String before=hash(source);Files.copy(source,copy);if(!before.equals(hash(source))||!before.equals(hash(copy)))throw new IOException("Input changed during capture: "+key);captured.put(key,name);hashes.put(name,before);}if(!Files.isDirectory(directory))throw new IOException("Input capture directory disappeared");manifest.put("captured_input_sha256",hashes);return captured;}
    private static void checkInputs(Path root,Map<String,Object> manifest,Map<String,Object> r)throws IOException {Object v=manifest.get("captured_input_sha256");if(!(v instanceof Map<?,?> hashes))throw new IOException("Missing raw input hashes");Set<String> expected=new HashSet<>();for(String key:INPUTS)if(r.get(key)!=null)expected.add(text(r,key));if(!hashes.keySet().equals(expected))throw new IOException("Raw input hash population changed");for(var entry:hashes.entrySet()){String name=(String)entry.getKey();if(!name.matches("input/file-[0-9]+")||!hash(root.resolve(name)).equals(entry.getValue()))throw new IOException("Captured raw input changed");}}
    private static Map<String,Object> diagnostics(Prepared p){Map<String,Object> d=new LinkedHashMap<>();d.put("peaks",p.counts.peaks().size());d.put("cells",p.counts.cells().size());d.put("motifs",p.annotations.ids().size());d.put("background_iterations",p.iterations);d.put("annotation_format",p.annotations.format());d.put("repeated_annotation_members",p.annotations.repeatedMembers());d.put("missing_group_assignments",p.missingGroups);d.put("supplied_expectation",p.suppliedExpectation);d.put("stored_count_values",p.counts.values().length);d.put("native_work",p.result.work());Map<String,Object> kinds=new LinkedHashMap<>();for(var kind:ChromVarDeviations.Kind.values())kinds.put(kind.name(),0L);for(double[] row:p.result.z())for(double value:row){String key=ChromVarDeviations.kind(value).name();kinds.put(key,(long)kinds.get(key)+1);}d.put("z_value_kinds",kinds);return d;}
    private static void tables(Path root,Prepared p,boolean compare,long maximumBytes)throws IOException {
        try(var table=new Table(root.resolve("expectations.tsv"),compare,maximumBytes)){table.line("peak_id\texpectation");for(int i=0;i<p.expectation.length;i++)table.line(p.counts.peaks().get(i)+"\t"+ChromVarDeviations.format(p.expectation[i]));}
        double[] matches=p.result.fractionMatches(),overlap=p.result.fractionBackgroundOverlap();try(var table=new Table(root.resolve("motif-summary.tsv"),compare,maximumBytes)){table.line("motif_id\tmotif_name\tfraction_matches\tfraction_background_overlap");for(int i=0;i<matches.length;i++)table.line(p.annotations.ids().get(i)+"\t"+p.annotations.names().get(i)+"\t"+ChromVarDeviations.format(matches[i])+"\t"+ChromVarDeviations.format(overlap[i]));}
        double[][] z=p.result.z(),deviations=p.result.deviations();try(var table=new Table(root.resolve("deviations.tsv"),compare,maximumBytes)){table.line("motif_id\tcell_id\tdeviation\tz");for(int motif=0;motif<z.length;motif++)for(int cell=0;cell<z[motif].length;cell++)table.line(p.annotations.ids().get(motif)+"\t"+p.counts.cells().get(cell)+"\t"+ChromVarDeviations.format(deviations[motif][cell])+"\t"+ChromVarDeviations.format(z[motif][cell]));}
    }
    private static final class Table implements AutoCloseable {
        private final OutputStream out;private final BufferedReader in;private final long maximum;private long bytes;
        Table(Path path,boolean compare,long maximum)throws IOException{this.maximum=maximum;if(compare){if(!Files.isRegularFile(path)||Files.size(path)>maximum)throw new IOException("Result table unavailable/excessive");in=Files.newBufferedReader(path,StandardCharsets.UTF_8);out=null;}else{out=new BufferedOutputStream(Files.newOutputStream(path,StandardOpenOption.CREATE_NEW));in=null;}}
        void line(String value)throws IOException{if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException("ChromVAR table interrupted");byte[] raw=(value+"\n").getBytes(StandardCharsets.UTF_8);if(raw.length>maximum-bytes)throw new IOException("Result byte capacity exceeded");bytes+=raw.length;if(out!=null)out.write(raw);else if(!Objects.equals(in.readLine(),value))throw new IOException("Recomputed native result table differs");}
        @Override public void close()throws IOException{if(out!=null)out.close();if(in!=null)try{if(in.readLine()!=null)throw new IOException("Excess native result rows");}finally{in.close();}}
    }
    private static void copySources(Path root)throws IOException {Path dir=Files.createDirectory(root.resolve("source"));for(String name:sourceNames()){Path target=dir.resolve(name);Files.createDirectories(target.getParent());Files.write(target,resource(name),StandardOpenOption.CREATE_NEW);}}
    private static void validateSources(Path root)throws IOException {for(String name:sourceNames())if(!Arrays.equals(resource(name),Files.readAllBytes(root.resolve("source").resolve(name))))throw new IOException("Captured original function/notice differs: "+name);}
    private static List<String> sourceNames(){List<String> names=new ArrayList<>(List.of("SOURCE-PROFILES.json","MIT-LICENSE.txt"));for(String edition:List.of("1.16.0","1.34.1"))for(String function:List.of("compute_expectations_core","compute_deviations_core","compute_deviations_single"))names.add(edition+"/"+function+".R");return names;}
    private static byte[] resource(String name)throws IOException {try(var in=ChromVarRequestCli.class.getResourceAsStream("/org/jlinalg/omics/chromvar-deviations/"+name)){if(in==null)throw new IOException("Missing original source resource");return in.readAllBytes();}}
    private static String warningText(List<String> warnings,int code){return (code==0?"# WARNINGS / REQUIRED ACTIONS — NATIVE CHROMVAR\n":"# FAIL2 — NO CHROMVAR RESULT ADMITTED\n")+"\n"+String.join("\n\n",new LinkedHashSet<>(warnings))+"\n\nRequired action: "+ACTION+"\n";}
    private static void seal(Path root)throws IOException {Path inventory=root.resolve("artifact-checksums.tsv");try(var out=Files.newBufferedWriter(inventory,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);var files=Files.walk(root)){out.write("sha256\tpath\n");for(Path path:files.filter(Files::isRegularFile).filter(p->!p.equals(inventory)).sorted().toList())out.write(hash(path)+"\t"+root.relativize(path).toString().replace('\\','/')+"\n");}}
    private static void inventory(Path root)throws IOException {
        Path inventory=root.resolve("artifact-checksums.tsv");if(!Files.isRegularFile(inventory)||Files.size(inventory)>10_000_000)throw new IOException("Missing/excessive chromVAR inventory");var lines=Files.readAllLines(inventory,StandardCharsets.UTF_8);if(lines.isEmpty()||!lines.get(0).equals("sha256\tpath"))throw new IOException("Invalid chromVAR inventory header");Set<String> seen=new HashSet<>();for(String line:lines.subList(1,lines.size())){String[] f=line.split("\t",-1);if(f.length!=2||!f[0].matches("[0-9a-f]{64}")||f[1].contains(":")||f[1].contains("\\")||Arrays.stream(f[1].split("/",-1)).anyMatch(v->Set.of("",".","..").contains(v)))throw new IOException("Unsafe chromVAR inventory path");Path path=root.resolve(f[1]);if(!seen.add(f[1])||!Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS)||!hash(path).equals(f[0]))throw new IOException("ChromVAR inventory hash/population differs");}
        try(var files=Files.walk(root)){for(Path path:files.toList()){if(Files.isSymbolicLink(path))throw new IOException("Captured symlink forbidden");if(Files.isRegularFile(path)&&!path.equals(inventory)&&!seen.contains(root.relativize(path).toString().replace('\\','/')))throw new IOException("Uninventoried captured file");}}
    }
    private static void verify(Path root)throws IOException {
        inventory(root);var manifest=read(root.resolve("manifest.json"));var status=read(root.resolve("analysis-status.json"));if(!"completed-with-warnings".equals(manifest.get("analysis_status"))||!Objects.equals(status.get("status"),manifest.get("analysis_status"))||!"DEVIATIONS".equals(manifest.get("mode"))||!"native-java".equals(manifest.get("engine")))throw new IOException("Native chromVAR did not complete");for(String key:List.of("upstream_background_sampling_performed","motif_scanning_performed","historical_whole_packages_executed","full_Signac_workflow_available"))if(!Boolean.FALSE.equals(manifest.get(key)))throw new IOException("Native chromVAR scope changed");var original=read(root.resolve("source-request.json"));validate(original);var current=read(root.resolve("request.json"));Map<String,Object> expected=new LinkedHashMap<>(original);expected.put("out",".");int index=0;for(String key:INPUTS)if(original.get(key)!=null)expected.put(key,"input/file-"+index++);if(!expected.equals(current)||!Objects.equals(manifest.get("source_request_sha256"),hash(root.resolve("source-request.json")))||!Objects.equals(manifest.get("profile"),current.get("profile")))throw new IOException("Native request/source binding changed");checkInputs(root,manifest,current);validateSources(root);Prepared p=prepare(current,root);if(!NextflowJson.json(diagnostics(p)).equals(NextflowJson.json(read(root.resolve("diagnostics.json")))))throw new IOException("Native chromVAR diagnostics changed");tables(root,p,true,integer(current,"maximum_output_bytes",2_000_000_000L,1,20_000_000_000L));if(!Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warningText(p.warnings,0)))throw new IOException("Native warnings/actions changed");if(!NextflowJson.json(Map.of("schema_version",1,"mode","VERIFY","analysis",".")).equals(NextflowJson.json(read(root.resolve("verify-request.json")))))throw new IOException("Generated VERIFY request changed");
    }
    private static ChromVarDeviations.Profile profile(Map<String,Object> r)throws IOException {return switch(text(r,"profile")){case "1.16.0-source"->ChromVarDeviations.Profile.SOURCE_1_16_0;case "1.34.1-package"->ChromVarDeviations.Profile.SOURCE_1_34_1;default->throw new IOException("Choose explicit 1.16.0-source or1.34.1-package numerical source profile; no historical version substitution occurs");};}
    private static long integer(Map<String,Object> r,String key,long fallback,long min,long max)throws IOException {Object value=r.getOrDefault(key,fallback);if(!(value instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()!=Math.rint(n.doubleValue())||n.doubleValue()<min||n.doubleValue()>max)throw new IOException("Invalid bounded integer field: "+key);return n.longValue();}
    private static void schema(Map<String,Object> r)throws IOException {if(!(r.get("schema_version") instanceof Number n)||n.doubleValue()!=1)throw new IOException("Require schema_version1");}
    private static void keys(Map<String,Object> r,Set<String> allowed)throws IOException {for(String key:r.keySet())if(!allowed.contains(key))throw new IOException("Unknown chromVAR request field: "+key);}
    private static String text(Map<String,Object> r,String key)throws IOException {if(!(r.get(key) instanceof String value)||value.isBlank())throw new IOException("Require nonblank field: "+key);return value;}
    private static Path resolve(Path parent,String value,boolean captured)throws IOException {Path path=parent.resolve(Path.of(value)).toAbsolutePath().normalize();if(captured&&(!path.startsWith(parent)||Files.isSymbolicLink(path)))throw new IOException("Captured input escapes analysis directory");return path;}
    private static Path input(Map<String,Object> r,String key,Path root)throws IOException {return resolve(root,text(r,key),true);}
    private static Map<String,Object> read(Path path)throws IOException {if(!Files.isRegularFile(path)||Files.size(path)>1_000_000)throw new IOException("ChromVAR JSON unavailable/excessive");Object value=SimpleJson.parse(Files.readString(path,StandardCharsets.UTF_8));if(!(value instanceof Map<?,?> map))throw new IOException("Expected a JSON object");Map<String,Object> result=new LinkedHashMap<>();for(var e:map.entrySet())result.put((String)e.getKey(),e.getValue());return result;}
    private static void json(Path path,Map<String,Object> value)throws IOException {Files.writeString(path,NextflowJson.json(value),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);}
    private static void emit(PrintStream out,String message){out.writeBytes((message+"\n").getBytes(StandardCharsets.UTF_8));}
}
